    pwd = "aAaBbcdefgh1!"  # 'aAa' is not a repeat
    assert check_password(pwd, "zz", set()) == []


def test_repeat_at_end_detected():
    pwd = "Abcdefghijk!!!"
    assert check_password(pwd, "zz", set()) == ["REPEAT"]


