    pwd = GOOD
    assert check_password(pwd, "zz", {"horse"}) == []


def test_blocklist_entry_stored_mixed_case_matches():
    pwd = GOOD
    assert check_password(pwd, "zz", {"Tr0ub4dor&horse"}) == ["BLOCKLIST"]


